   595  static int handle_data_frame(h2o_http2_conn_t *conn, h2o_http2_frame_t *frame, const char **err_desc)
   596  {
   597      h2o_http2_data_payload_t payload;
   598      h2o_http2_stream_t *stream;
   599      int ret;
   600
   601      if ((ret = h2o_http2_decode_data_payload(&payload, frame, err_desc)) != 0)
   602          return ret;
   603
   604      if (conn->state >= H2O_HTTP2_CONN_STATE_HALF_CLOSED)
   605          return 0;
   606
   607      update_input_window(conn, 0, &conn->_input_window, payload.length);
   608
   609      stream = h2o_http2_conn_get_stream(conn, frame->stream_id);
   610
   611      /* save the input in the request body buffer, or send error (and close the stream) */
   612      if (stream == NULL) {
   613          if (frame->stream_id <= conn->pull_stream_ids.max_open) {
   614              stream_send_error(conn, frame->stream_id, H2O_HTTP2_ERROR_STREAM_CLOSED);
   615              stream = NULL;
   616          } else {
   617              *err_desc = "invalid DATA frame";
   618              return H2O_HTTP2_ERROR_PROTOCOL;
   619          }
   620      } else if (stream->state != H2O_HTTP2_STREAM_STATE_RECV_BODY) {
   621          stream_send_error(conn, frame->stream_id, H2O_HTTP2_ERROR_STREAM_CLOSED);
   622          h2o_http2_stream_reset(conn, stream);
   623          stream = NULL;
   624      } else if (h2o_http2_stream_req_body_size(stream) + payload.length > conn->super.ctx->globalconf->max_request_entity_size) {
   625          stream_send_error(conn, frame->stream_id, H2O_HTTP2_ERROR_REFUSED_STREAM);
   626          h2o_http2_stream_reset(conn, stream);
   627          stream = NULL;
   628      } else {
   629          int ret;
   630
   631          if (!stream->request_blocked_by_server) {
   632              h2o_http2_stream_set_request_blocked_by_server(conn, stream, 1);
   633              update_idle_timeout(conn);
   634          }
   635
   636          ret = stream->req._write_req_chunk.cb(stream->req._write_req_chunk.priv, h2o_iovec_init(payload.data, payload.length),
   637                                                frame->flags & H2O_HTTP2_FRAME_FLAG_END_STREAM);
   638          if (ret < 0) {
   639              stream_send_error(conn, frame->stream_id, H2O_HTTP2_ERROR_STREAM_CLOSED);
   640              h2o_http2_stream_reset(conn, stream);
   641              stream = NULL;
   642              goto UpdateWindow;
   643          }
   644          return 0;
   645      }
   646
   647  UpdateWindow:
   648      /* consume buffer (and set window_update) */
   649      update_input_window(conn, 0, &conn->_input_window, frame->length);
   650      if (stream != NULL)
   651          update_input_window(conn, stream->stream_id, &stream->input_window, frame->length);
   652
   653      return 0;
   654  }
